class Solution:
    def bstToGst(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        self.total = 0
        def traverse(node: Optional[TreeNode]):
            if not node:
                return
            traverse(node.right)
            self.total += node.val
            node.val = self.total
            traverse(node.left)
        traverse(root)
        return root

class Solution {
public:
    TreeNode* bstToGst(TreeNode* root) {
        int total = 0;
        auto traverse = [&](auto& self, TreeNode* node) -> void {
            if (!node) return;
            self(self, node->right);
            total += node->val;
            node->val = total;
            self(self, node->left);
        };
        traverse(traverse, root);
        return root;
    }
};

class Solution {
    private int total = 0;

    public TreeNode bstToGst(TreeNode root) {
        total = 0;
        traverse(root);
        return root;
    }

    private void traverse(TreeNode node) {
        if (node == null) return;
        traverse(node.right);
        total += node.val;
        node.val = total;
        traverse(node.left);
    }
}

